CREATE UNIQUE INDEX IF NOT EXISTS drawing_architecture_exception_adj_project_key_idx
  ON drawing_architecture_exception_adjudications (project_id, exception_key)
  WHERE superseded_at IS NULL;

CREATE UNIQUE INDEX estimator_understanding_single_controlled_retry_idx
ON estimator_understanding_runs(parent_run_id, authorization_fingerprint)
WHERE run_mode='CONTROLLED_RETRY';

CREATE INDEX library_products_product_role_idx
ON library_products (
  product_role,
  identity_status,
  review_status
);

CREATE UNIQUE INDEX IF NOT EXISTS spec_candidate_decisions_one_promotion_per_clause_idx
  ON specification_clause_candidate_decisions (clause_id)
  WHERE decision = 'Promoted';

CREATE UNIQUE INDEX IF NOT EXISTS spec_candidate_decisions_one_requirement_per_promotion_idx
  ON specification_clause_candidate_decisions (requirement_id)
  WHERE decision = 'Promoted' AND requirement_id IS NOT NULL;

